            {"after": 3, "q": "What crop did they plant the first year, and who benefited?", "options": ["Grain, and the bear benefited", "Turnips, and the fox benefited", "Turnips, and the bear benefited", "Grain, and the fox lost everything"], "correct": 1},
            {"after": 5, "q": "What happened with the second crop?", "options": ["The bear finally got the better share", "The fox again took the valuable part", "They shared it equally this time", "The harvest failed completely"], "correct": 1},
