            {"after": 3, "q": "What happened in Loki's eating contest against Logi?", "options": ["Loki won easily", "Loki lost badly, since Logi devoured meat, bones and trough alike", "They tied and shared the meat", "Loki refused to compete"], "correct": 1},
            {"after": 5, "q": "What were the three trials Thor faced?", "options": ["Wrestling, archery, and swimming", "Drinking a horn, lifting a cat, and wrestling an old woman", "Climbing a mountain, lifting a stone, and a footrace", "Singing, drinking, and jumping"], "correct": 1},
            {"after": 6, "q": "What was the horn Thor drank from actually connected to?", "options": ["A well beneath the castle", "The ocean, so his draughts caused the tides to ebb", "A river of fire", "Nothing — it was simply a very deep horn"], "correct": 1},
